from dataclasses import dataclass, replace
from enum import Enum
from typing import Optional, Sequence

from .errors import Failure, FailureCode
from .ids import Badge, DepartmentId, Period, ReportId
from .lines import Line

MAX_LINES = 50
MAX_APPROVALS = 2      # a third approval completes the chain, so a Submitted report never holds three


class ReportStatus(Enum):
    DRAFT = "Draft"
    SUBMITTED = "Submitted"
    APPROVED = "Approved"
    REJECTED = "Rejected"
    CHANGES_REQUESTED = "ChangesRequested"
    PAID = "Paid"


TRANSITIONS = {
    ReportStatus.DRAFT: {ReportStatus.SUBMITTED},
    ReportStatus.SUBMITTED: {ReportStatus.APPROVED, ReportStatus.REJECTED, ReportStatus.CHANGES_REQUESTED},
    ReportStatus.CHANGES_REQUESTED: {ReportStatus.SUBMITTED},
    ReportStatus.APPROVED: {ReportStatus.PAID},
    ReportStatus.REJECTED: set(),
    ReportStatus.PAID: set(),
}


@dataclass(frozen=True)
class Report:
    id: ReportId
    badge: Badge
    department: DepartmentId
    period: Period
    lines: Sequence[Line]
    status: ReportStatus
    approvals: Sequence[Badge] = ()
    reference: Optional[str] = None      # set only once Paid


def _enter(r: Report, status: ReportStatus, **fields) -> Report:
    if status not in TRANSITIONS[r.status]:
        raise Failure(FailureCode.CONFLICT, f"a {r.status.value} report cannot become {status.value}")
    return replace(r, status=status, **fields)


def editable(r: Report) -> bool:
    return r.status in (ReportStatus.DRAFT, ReportStatus.CHANGES_REQUESTED)


def add_line(r: Report, line: Line) -> Report:
    if not editable(r) or len(r.lines) >= MAX_LINES:
        raise Failure(FailureCode.CONFLICT, "the report cannot take another line")
    return replace(r, lines=(*r.lines, line))


def submit(r: Report) -> Report:
    return _enter(r, ReportStatus.SUBMITTED, approvals=())


def add_approval(r: Report, who: Badge) -> Report:
    if r.status is not ReportStatus.SUBMITTED or len(r.approvals) >= MAX_APPROVALS:
        raise Failure(FailureCode.CONFLICT, "the report is not awaiting another approval")
    return replace(r, approvals=(*r.approvals, who))


def approve(r: Report) -> Report:
    return _enter(r, ReportStatus.APPROVED)


def reject(r: Report) -> Report:
    return _enter(r, ReportStatus.REJECTED)


def request_changes(r: Report) -> Report:
    return _enter(r, ReportStatus.CHANGES_REQUESTED, approvals=())


def resubmit(r: Report) -> Report:
    return _enter(r, ReportStatus.SUBMITTED, approvals=())


def pay(r: Report, reference: str) -> Report:
    return _enter(r, ReportStatus.PAID, reference=reference)


def counts_as_spend(r: Report) -> bool:
    return r.status in (ReportStatus.APPROVED, ReportStatus.PAID)

"""Drafting, submitting, and reviewing expense reports."""
from typing import Optional

from . import lines, reports, routing
from .audit import Entry
from .budget import spend_of
from .errors import Failure, FailureCode
from .host import Store
from .ids import Badge, Period, ReportId, Role
from .lines import Line
from .reports import Report, ReportStatus
from .staff import Staff


def open_draft(store: Store, badge: Badge, period: Period, first_line: Line) -> ReportId:
    who = store.staff(badge)
    if not who.active:
        raise Failure(FailureCode.UNAUTHORIZED, "staff member is not active")
    if store.period_closed(period):
        raise Failure(FailureCode.CONFLICT, "the period is closed")
    id = store.next_id()
    store.save_report(Report(id, badge, who.department, period, (first_line,), ReportStatus.DRAFT))
    return id


def add_line(store: Store, report_id: ReportId, badge: Badge, line: Line) -> None:
    r = _own(store, report_id, badge)
    if not reports.editable(r):
        raise Failure(FailureCode.CONFLICT, "the report is not editable")
    if len(r.lines) >= reports.MAX_LINES:
        raise Failure(FailureCode.INVALID_INPUT, "a report holds at most 50 lines")
    store.save_report(reports.add_line(r, line))


def submit(store: Store, report_id: ReportId, badge: Badge) -> None:
    r = _own(store, report_id, badge)
    if r.status is not ReportStatus.DRAFT:
        raise Failure(FailureCode.CONFLICT, "the report is not a draft")
    _open_and_valid(store, r)
    store.save_report(reports.submit(r))
    store.append_audit(Entry(badge, r.id, ReportStatus.DRAFT, ReportStatus.SUBMITTED, "submitted"))


def resubmit(store: Store, report_id: ReportId, badge: Badge) -> None:
    r = _own(store, report_id, badge)
    if r.status is not ReportStatus.CHANGES_REQUESTED:
        raise Failure(FailureCode.CONFLICT, "the report is not awaiting changes")
    _open_and_valid(store, r)
    store.save_report(reports.resubmit(r))
    store.append_audit(Entry(badge, r.id, ReportStatus.CHANGES_REQUESTED, ReportStatus.SUBMITTED, "resubmitted"))


def approve(store: Store, report_id: ReportId, approver: Badge) -> ReportStatus:
    r, who = _gate(store, report_id, approver)
    if len(r.approvals) + 1 >= routing.steps_for(lines.total(r.lines)):
        return _final_approval(store, r, who)
    store.save_report(reports.add_approval(r, who.badge))
    store.append_audit(Entry(who.badge, r.id, ReportStatus.SUBMITTED, ReportStatus.SUBMITTED, "approved; awaiting the next approver"))
    return ReportStatus.SUBMITTED


def reject(store: Store, report_id: ReportId, approver: Badge, reason: str) -> None:
    r, who = _gate(store, report_id, approver)
    store.save_report(reports.reject(r))
    store.append_audit(Entry(who.badge, r.id, ReportStatus.SUBMITTED, ReportStatus.REJECTED, reason))


def request_changes(store: Store, report_id: ReportId, approver: Badge, reason: str) -> None:
    r, who = _gate(store, report_id, approver)
    store.save_report(reports.request_changes(r))
    store.append_audit(Entry(who.badge, r.id, ReportStatus.SUBMITTED, ReportStatus.CHANGES_REQUESTED, reason))


def may_act(store: Store, r: Report, who: Staff) -> bool:
    """Is `who` the required approver for the report's next step? Raises Conflict when no one can be."""
    required = _required_for(store, r)
    if required is None:
        return who.role is Role.FINANCE
    return who.badge == required


def _own(store: Store, report_id: ReportId, badge: Badge) -> Report:
    who = store.staff(badge)
    if not who.active:
        raise Failure(FailureCode.UNAUTHORIZED, "staff member is not active")
    r = store.report(report_id)
    if r.badge != badge:
        raise Failure(FailureCode.UNAUTHORIZED, "only the submitter may act on this report")
    return r


def _open_and_valid(store: Store, r: Report) -> None:
    if store.period_closed(r.period):
        raise Failure(FailureCode.CONFLICT, "the period is closed")
    if not lines.all_valid(r.lines):
        raise Failure(FailureCode.INVALID_INPUT, "a line is over its limit or lacks a required receipt")


def _gate(store: Store, report_id: ReportId, approver: Badge) -> tuple[Report, Staff]:
    who = store.staff(approver)
    if not who.active:
        raise Failure(FailureCode.UNAUTHORIZED, "staff member is not active")
    r = store.report(report_id)
    if r.status is not ReportStatus.SUBMITTED:
        raise Failure(FailureCode.CONFLICT, "the report is not awaiting approval")
    if store.period_closed(r.period):
        raise Failure(FailureCode.CONFLICT, "the period is closed")
    if who.badge == r.badge:
        raise Failure(FailureCode.UNAUTHORIZED, "a report cannot be approved by its submitter")
    if not may_act(store, r, who):
        raise Failure(FailureCode.UNAUTHORIZED, "not this report's next approver")
    return r, who


def _required_for(store: Store, r: Report) -> Optional[Badge]:
    """The badge required for the next step, or None when any active finance staff member will do."""
    role = routing.role_for(len(r.approvals) + 1)
    if role is Role.FINANCE:
        return None
    if role is Role.SUPERVISOR:
        submitter = store.staff(r.badge)
        if submitter.supervisor is None:
            raise Failure(FailureCode.CONFLICT, "the submitter has no supervisor")
        return _stand_in(store, submitter.supervisor)
    return _stand_in(store, store.department(r.department).director)


def _stand_in(store: Store, required: Badge) -> Badge:
    person = store.staff(required)
    if person.active:
        return required
    if person.supervisor is not None and store.staff(person.supervisor).active:
        return person.supervisor
    raise Failure(FailureCode.CONFLICT, f"no active approver stands in for {required}")


def _final_approval(store: Store, r: Report, who: Staff) -> ReportStatus:
    dept = store.department(r.department)
    within = spend_of(store.reports_for(r.department, r.period)) + lines.budgeted_total(r.lines) <= dept.budget
    if not within and who.role is not Role.FINANCE:
        raise Failure(FailureCode.CONFLICT, "the department budget for this period would be exceeded")
    store.save_report(reports.approve(r))
    store.append_audit(Entry(who.badge, r.id, ReportStatus.SUBMITTED, ReportStatus.APPROVED,
                             "approved" if within else "approved; budget override"))
    return ReportStatus.APPROVED

"""Read-only views."""
from dataclasses import dataclass
from typing import Sequence

from . import lines
from .budget import spend_of
from .errors import Failure, FailureCode
from .host import Store
from .ids import Badge, DepartmentId, Period, ReportId
from .reports import ReportStatus, counts_as_spend
from .review import may_act


def spend(store: Store, department: DepartmentId, period: Period) -> int:
    dept = store.department(department)
    return spend_of(store.reports_for(dept.id, period))


@dataclass(frozen=True)
class Row:
    id: ReportId
    badge: Badge
    status: ReportStatus
    total: int
    budgeted: int


@dataclass(frozen=True)
class Statement:
    department: DepartmentId
    period: Period
    budget: int
    spend: int
    remaining: int                 # negative after a finance override
    rows: Sequence[Row]


def statement(store: Store, department: DepartmentId, period: Period) -> Statement:
    dept = store.department(department)
    reports = store.reports_for(dept.id, period)
    rows = tuple(Row(r.id, r.badge, r.status, lines.total(r.lines), lines.budgeted_total(r.lines)) for r in reports if counts_as_spend(r))
    spent = spend_of(reports)
    return Statement(dept.id, period, dept.budget, spent, dept.budget - spent, rows)


def pending_for(store: Store, approver: Badge) -> list[ReportId]:
    who = store.staff(approver)
    if not who.active:
        return []
    pending = []
    for r in store.submitted_reports():
        if r.status is not ReportStatus.SUBMITTED or r.badge == who.badge:
            continue
        try:
            if may_act(store, r, who):
                pending.append(r.id)
        except Failure as f:
            if f.code is not FailureCode.CONFLICT:        # no determinable approver: not pending for anyone
                raise
    return pending

from typing import Sequence

from .lines import budgeted_total
from .reports import Report, counts_as_spend


def spend_of(reports: Sequence[Report]) -> int:
    return sum(budgeted_total(r.lines) for r in reports if counts_as_spend(r))

from .ids import Role

SUPERVISOR_ONLY_UP_TO = 50_000
DIRECTOR_UP_TO = 500_000

STEP_ROLES = (Role.SUPERVISOR, Role.DIRECTOR, Role.FINANCE)


def steps_for(total: int) -> int:
    if total <= SUPERVISOR_ONLY_UP_TO:
        return 1
    if total <= DIRECTOR_UP_TO:
        return 2
    return 3


def role_for(step: int) -> Role:
    return STEP_ROLES[step - 1]

from dataclasses import dataclass
from typing import Sequence

from .ids import Category, Money

MAX_LINES = 50


@dataclass(frozen=True)
class Line:
    category: Category
    amount: Money
    description: str
    receipt: bool


@dataclass(frozen=True)
class Policy:
    limit: Money
    receipt_over: Money
    budgeted: bool


POLICIES = {
    Category.FEED: Policy(200_000, 2_500, True),
    Category.VETERINARY: Policy(500_000, 2_500, True),
    Category.CONTAINMENT: Policy(1_000_000, 5_000, True),
    Category.EQUIPMENT: Policy(300_000, 2_500, True),
    Category.TRAVEL: Policy(150_000, 2_500, True),
    Category.OTHER: Policy(50_000, 2_500, True),
}


def policy_for(category: Category) -> Policy:
    return POLICIES[category]


def line_valid(line: Line) -> bool:
    policy = policy_for(line.category)
    return line.amount <= policy.limit and (line.amount <= policy.receipt_over or line.receipt)


def all_valid(lines: Sequence[Line]) -> bool:
    return 1 <= len(lines) <= MAX_LINES and all(line_valid(l) for l in lines)


def total(lines: Sequence[Line]) -> int:
    return sum(l.amount for l in lines)


def budgeted_total(lines: Sequence[Line]) -> int:
    return sum(l.amount for l in lines if policy_for(l.category).budgeted)

